"""Team-authored bilingual definitions shown only with retrieved source evidence."""
DEFINITIONS = {
 'soil_moisture': ('Soil moisture is water held in the soil. This project uses GLDAS modeled water content in the top 0–10 cm, measured in kg/m², not automatically a percentage. It is a land-surface model estimate, not a direct measurement at every location.', 'رطوبة التربة هي كمية المياه الموجودة داخل التربة. يستخدم المشروع تقديرات GLDAS لمياه الطبقة السطحية بعمق 0–10 سم، بوحدة كيلوجرام لكل متر مربع وليست نسبة مئوية تلقائيًا. هي تقديرات نموذج لسطح الأرض، وليست قياسات مباشرة لكل مكان.'),
 'air_temperature': ('Air temperature describes how warm or cold the air is. This project uses MERRA-2 estimates at two metres above the surface, in kelvin. Subtract 273.15 to convert a temperature to Celsius. This is reanalysis, not a direct satellite temperature observation.', 'حرارة الهواء تصف مدى سخونة أو برودة الهواء. يستخدم المشروع تقديرات MERRA-2 على ارتفاع مترين، بوحدة كلفن. للتحويل للمئوية نطرح 273.15 من قيمة الحرارة. المنتج إعادة تحليل، وليس قياس حرارة مباشرًا من القمر الصناعي.'),
 'precipitation': ('Precipitation is water falling from the atmosphere, such as rain. The project uses IMERG monthly precipitation rates and converts them to monthly millimetres using the actual month duration. Annual values sum complete monthly amounts; uncertainty and spatial averaging limit interpretation.', 'الهطول هو المياه التي تسقط من الغلاف الجوي مثل المطر. يستخدم المشروع معدلات IMERG الشهرية ويحوّلها إلى كمية بالملليمتر وفق المدة الفعلية للشهر، ثم يجمع الشهور المكتملة لحساب الإجمالي السنوي. عدم اليقين والمتوسطات المكانية يحدّان من تفسير النتائج.'),
 'vegetation_greenness': ('NDVI is a unitless index of vegetation greenness derived from red and near-infrared reflectance. It is not a direct measure of crop yield or a complete drought diagnosis. This project uses MOD13C2 and retains only cells meeting its selected quality policy.', 'NDVI مؤشر بدون وحدة لاخضرار الغطاء النباتي، مشتق من الانعكاس في الأحمر والأشعة تحت الحمراء القريبة. ليس قياسًا مباشرًا للإنتاج الزراعي أو تشخيصًا كاملًا للجفاف. يستخدم المشروع MOD13C2 مع الاحتفاظ بالخلايا المقبولة وفق سياسة الجودة المختارة.')}

def definition_answer(variable, language):
    return DEFINITIONS[variable][language == 'ar']
